mapper.select:
SELECT gateway_code, gateway_name, channel_type, protocol_type, sign_algorithm, endpoint, status, status_type, DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i:%s') AS updatedAt FROM t_gateway_channel
( gateway_code LIKE CONCAT('%', #{query.keyword}, '%') OR gateway_name LIKE CONCAT('%', #{query.keyword}, '%') OR endpoint LIKE CONCAT('%', #{query.keyword}, '%') )
AND channel_type = #{query.channelType}
AND status = #{query.status}
ORDER BY id ASC

SELECT request_id, app_code, gateway_code, operation_type, sign_type, client_ip, result_status, result_status_type, risk_hint, DATE_FORMAT(happened_at, '%Y-%m-%d %H:%i:%s') AS happenedAt FROM t_gateway_audit_log
( request_id LIKE CONCAT('%', #{query.keyword}, '%') OR app_code LIKE CONCAT('%', #{query.keyword}, '%') OR gateway_code LIKE CONCAT('%', #{query.keyword}, '%') )
AND app_code = #{query.appCode}
AND result_status = #{query.resultStatus}
ORDER BY id DESC

SELECT route_code, gateway_code, environment, release_strategy, traffic_percent, release_window, status, status_type, DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i:%s') AS updatedAt FROM t_gateway_release_route
environment = #{query.environment}
AND status = #{query.status}
ORDER BY id ASC
